def ly(text, basis, conf, cm, ru, disp, reason):
    return {"prediction_text": text, "basis": basis, "confidence": conf,
            "trigger": {"changed_main": cm, "reserve_used": ru, "disputed": disp, "reason": reason}}

def bz(text, basis, conf):
    return {"prediction_text": text, "basis": basis, "confidence": conf,
            "trigger": {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}}

