os.makedirs(OUT, exist_ok=True)
written = []
for cid in IDS:
    d = P[cid]
    rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    path = os.path.join(OUT, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    written.append(path)

# verify: re-read every file, check case_id alignment and fields
assert len(written) == len(IDS), (len(written), len(IDS))
cnt = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in IDS:
    path = os.path.join(OUT, cid + ".json")
    with open(path, encoding="utf-8") as f:
        rec = json.load(f)
    assert rec["case_id"] == cid, cid
    for k in ("prediction_text", "basis", "confidence", "trigger"):
        assert k in rec and rec[k] not in (None, ""), (cid, k)
    assert 0.0 <= rec["confidence"] <= 1.0, cid
    t = rec["trigger"]
    for b in ("changed_main", "reserve_used", "disputed"):
        assert isinstance(t[b], bool), (cid, b)
        if cid.startswith("BQ") and t[b]:
            cnt[b] += 1
    assert isinstance(t["reason"], str), cid
    if not cid.startswith("BQ"):
        assert t == {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}, cid
print("OK written:", len(written))
print("liuyao trigger counts (BQ only):", cnt)
print("files:", [os.path.basename(p) for p in written])
